  public buyProperty(playerId: string, tileIndex?: number): void {
    if (this.state.phase !== "TURN_START" && this.state.phase !== "RESOLVING_TILE") {
      throw new Error(`الإجراء غير مسموح في المرحلة الحالية: ${this.state.phase}`);
